import{sanitizeHTML as e}from"./utils.js";import{t}from"./ui.js";export async function loadEfemerides(){const e=await fetch("./js/efemerides.json",{cache:"no-store"});if(!e.ok)throw new Error(`No se pudo cargar el archivo de efemérides (HTTP ${e.status})`);return e.json()}export function getTodayEfemeride(e,t=new Date){if(!e||!Array.isArray(e.efemerides))return null;const r=`${String(t.getDate()).padStart(2,"0")}/${String(t.getMonth()+1).padStart(2,"0")}`;return e.efemerides.find(e=>e.date===r)||null}export function renderEfemeride(r,i,n){if(!i)return;const s=i.closest("section");if(!r)return void(s&&(s.style.display="none"));s&&(s.style.display="");const a=document.getElementById("efemerides-date");a&&(a.textContent=r.date||"");const d=r[n]||r.ES||{},o=e(d.title||""),l=e(d.text||""),f=e(d.det||"");i.innerHTML=`\n    <article class="efemeride-item">\n      <div class="efemeride-header">\n        <span class="efemeride-icon" aria-hidden="true"><i class="fa-solid fa-calendar-day"></i></span>\n        <div>\n          <h3 class="efemeride-title">${o}</h3>\n          <p class="efemeride-text">${l}</p>\n        </div>\n      </div>\n      <details class="efemeride-details">\n        <summary data-i18n="efemerides.read_more">${e(t("efemerides.read_more"))}</summary>\n        <p class="efemeride-detail">${f}</p>\n      </details>\n    </article>`}